data.value:
select ROW_NUMBER() OVER (ORDER BY (select null)) AS SrNo,* from ( SELECT distinct 'A' as copy,1 as CopyNumber, AR_SET_Customer.CustomerName AS DealerName, SAL_DispatchHeader.DispatchNo, SAL_DispatchHeader.DispatchDate, ABS(INV_StockTransactionDetail.transactionQuantity) Quantity, SAL_DispatchHeader.GatePassNo, INV_SET_Category.CategoryName, INV_Item.Description as Item, [SAL_DispatchHeader].BiltyNo, [SAL_DispatchHeader].RefrenceNo as Chassis, [SAL_DispatchHeader].VehicleNo, [INV_Item].Description as Vehicle, INV_StockTransactionHeader.Comments as Engine, AR_SET_Customer.CustomerName, INV_Item.InventoryItemStatusCode as Model, Transporter.CustomerName as TransporterName, INV_StockTransactionDetail.Comments ,ISNULL((select LookupDetail.EnumeratedDescription from LookupDetail where LookUpDetailID = Sal_Dispatchheader.StatusCode and LookupHeaderID = 5),'') as DocumentStatus,Set_City.CityName FROM SAL_DispatchHeader INNER JOIN AR_SET_Customer ON SAL_DispatchHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_DispatchHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_DispatchHeader.PeriodID = AR_SET_Customer.PeriodID INNER JOIN INV_StockTransactionHeader ON INV_StockTransactionHeader.DocumentNo = SAL_DispatchHeader.DispatchNo AND INV_StockTransactionHeader.DocumentTypeID = SAL_DispatchHeader.DocumentTypeID AND INV_StockTransactionHeader.CompanyID = SAL_DispatchHeader.CompanyID AND INV_StockTransactionHeader.PeriodID = SAL_DispatchHeader.PeriodID INNER JOIN INV_StockTransactionDetail ON INV_StockTransactionDetail.stockTransactionID = INV_StockTransactionHeader.StockTransactionID AND INV_StockTransactionDetail.CompanyID = INV_StockTransactionHeader.CompanyID AND INV_StockTransactionDetail.PeriodID=INV_StockTransactionHeader.PeriodID INNER JOIN INV_Item On INV_Item.ItemID = INV_StockTransactionDetail.ItemID INNER JOIN INV_Set_Category ON INV_Set_Category.CategoryID = INV_Item.ItemTypeID -- LEFT JOIN AR_SET_Customer Transporter ON SAL_DispatchHeader.TransporterID = Transporter.CustomerID AND SAL_DispatchHeader.CompanyID = Transporter.CompanyID AND SAL_DispatchHeader.PeriodID = Transporter.PeriodID INNER JOIN [SET_DocumentType] ON [INV_StockTransactionHeader].[DocumentTypeID] = [SET_DocumentType].[DocumentTypeID] AND [INV_StockTransactionHeader].[CompanyID] = [SET_DocumentType].[CompanyID] AND [INV_StockTransactionHeader].[PeriodID] = [SET_DocumentType].[PeriodID] AND [SET_DocumentType].[Status] = 1 left Join Set_City ON Set_City.CityID = Sal_Dispatchheader.CityID AND Set_City.Status = 1 WHERE SAL_DispatchHeader.CompanyID = @CompanyID AND SAL_DispatchHeader.PeriodID = @PeriodID AND (INV_Set_Category.CategoryID = @CategoryID or @CategoryID is Null) {0} ) as tab -- for DOC number select ROW_NUMBER() OVER (ORDER BY (select null)) AS SrNo,* from ( SELECT 1 as CopyNumber, SAL_DispatchHeader.DispatchNo, SAL_DispatchHeader.GatePassNo FROM SAL_DispatchHeader LEFT JOIN SAL_DispatchVehicleInformation ON SAL_DispatchHeader.DispatchID = SAL_DispatchVehicleInformation.DispatchID AND SAL_DispatchHeader.CompanyID = SAL_DispatchVehicleInformation.CompanyID AND SAL_DispatchHeader.PeriodID = SAL_DispatchVehicleInformation.PeriodID INNER JOIN AR_SET_Customer ON SAL_DispatchHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_DispatchHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_DispatchHeader.PeriodID = AR_SET_Customer.PeriodID INNER JOIN INV_StockTransactionHeader ON INV_StockTransactionHeader.DocumentNo = SAL_DispatchHeader.DispatchNo AND INV_StockTransactionHeader.DocumentTypeID = SAL_DispatchHeader.DocumentTypeID AND INV_StockTransactionHeader.CompanyID = SAL_DispatchHeader.CompanyID AND INV_StockTransactionHeader.PeriodID = SAL_DispatchHeader.PeriodID inner JOIN INV_StockTransactionDetail ON INV_StockTransactionDetail.stockTransactionID = INV_StockTransactionHeader.StockTransactionID AND INV_StockTransactionDetail.CompanyID = INV_StockTransactionHeader.CompanyID AND INV_StockTransactionDetail.PeriodID=INV_StockTransactionHeader.PeriodID INNER JOIN INV_Item On INV_Item.ItemID = INV_StockTransactionDetail.ItemID --AND INV_Item.CompanyID = INV_StockTransactionDetail.CompanyID INNER JOIN INV_Set_Category ON INV_Set_Category.CategoryID = INV_Item.ItemTypeID -- LEFT JOIN AR_SET_Customer Transporter ON SAL_DispatchHeader.TransporterID = Transporter.CustomerID AND SAL_DispatchHeader.CompanyID = Transporter.CompanyID AND SAL_DispatchHeader.PeriodID = Transporter.PeriodID INNER JOIN [SET_DocumentType] ON [INV_StockTransactionHeader].[DocumentTypeID] = [SET_DocumentType].[DocumentTypeID] AND [INV_StockTransactionHeader].[CompanyID] = [SET_DocumentType].[CompanyID] AND [INV_StockTransactionHeader].[PeriodID] = [SET_DocumentType].[PeriodID] AND [SET_DocumentType].[Status] = 1 WHERE SAL_DispatchHeader.CompanyID = @CompanyID AND SAL_DispatchHeader.PeriodID = @PeriodID AND (INV_Set_Category.CategoryID = @CategoryID or @CategoryID is Null) {0}
union all
SELECT 2 as CopyNumber, SAL_DispatchHeader.DispatchNo, SAL_DispatchHeader.GatePassNo FROM SAL_DispatchHeader LEFT JOIN SAL_DispatchVehicleInformation ON SAL_DispatchHeader.DispatchID = SAL_DispatchVehicleInformation.DispatchID AND SAL_DispatchHeader.CompanyID = SAL_DispatchVehicleInformation.CompanyID AND SAL_DispatchHeader.PeriodID = SAL_DispatchVehicleInformation.PeriodID INNER JOIN AR_SET_Customer ON SAL_DispatchHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_DispatchHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_DispatchHeader.PeriodID = AR_SET_Customer.PeriodID INNER JOIN INV_StockTransactionHeader ON INV_StockTransactionHeader.DocumentNo = SAL_DispatchHeader.DispatchNo AND INV_StockTransactionHeader.DocumentTypeID = SAL_DispatchHeader.DocumentTypeID AND INV_StockTransactionHeader.CompanyID = SAL_DispatchHeader.CompanyID AND INV_StockTransactionHeader.PeriodID = SAL_DispatchHeader.PeriodID inner JOIN INV_StockTransactionDetail ON INV_StockTransactionDetail.stockTransactionID = INV_StockTransactionHeader.StockTransactionID AND INV_StockTransactionDetail.CompanyID = INV_StockTransactionHeader.CompanyID AND INV_StockTransactionDetail.PeriodID=INV_StockTransactionHeader.PeriodID INNER JOIN INV_Item On INV_Item.ItemID = INV_StockTransactionDetail.ItemID --AND INV_Item.CompanyID = INV_StockTransactionDetail.CompanyID INNER JOIN INV_Set_Category ON INV_Set_Category.CategoryID = INV_Item.ItemTypeID -- LEFT JOIN AR_SET_Customer Transporter ON SAL_DispatchHeader.TransporterID = Transporter.CustomerID AND SAL_DispatchHeader.CompanyID = Transporter.CompanyID AND SAL_DispatchHeader.PeriodID = Transporter.PeriodID INNER JOIN [SET_DocumentType] ON [INV_StockTransactionHeader].[DocumentTypeID] = [SET_DocumentType].[DocumentTypeID] AND [INV_StockTransactionHeader].[CompanyID] = [SET_DocumentType].[CompanyID] AND [INV_StockTransactionHeader].[PeriodID] = [SET_DocumentType].[PeriodID] AND [SET_DocumentType].[Status] = 1 WHERE SAL_DispatchHeader.CompanyID = @CompanyID AND SAL_DispatchHeader.PeriodID = @PeriodID AND (INV_Set_Category.CategoryID = @CategoryID or @CategoryID is Null) {0} ) as tab1
